// === Tab: mySketch ===
let nodes = [];

function setup() {
  createCanvas(windowWidth, windowHeight);
  background(8, 10, 18);

  for (let i = 0; i < 90; i++) {
    nodes.push(new NeuralCircle(random(width), random(height)));
  }
}

function draw() {
  background(8, 10, 18, 35);

  for (let n of nodes) {
    n.move();
    n.display();
  }

  connectNodes();
}

function connectNodes() {
  for (let i = 0; i < nodes.length; i++) {
    for (let j = i + 1; j < nodes.length; j++) {
      let d = dist(nodes[i].x, nodes[i].y, nodes[j].x, nodes[j].y);

      if (d < 130) {
        let alpha = map(d, 0, 130, 160, 0);
        stroke(120, 180, 255, alpha);
        strokeWeight(1);
        line(nodes[i].x, nodes[i].y, nodes[j].x, nodes[j].y);
      }
    }
  }
}

class NeuralCircle {
  constructor(x, y) {
    this.x = x;
    this.y = y;
    this.r = random(8, 28);
    this.baseR = this.r;
    this.angle = random(TWO_PI);
    this.speed = random(0.003, 0.012);
    this.phase = random(TWO_PI);
  }

  move() {
    this.angle += random(-0.04, 0.04);

    this.x += cos(this.angle) * 0.45;
    this.y += sin(this.angle) * 0.45;

    this.x = (this.x + width) % width;
    this.y = (this.y + height) % height;

    this.r = this.baseR + sin(frameCount * 0.04 + this.phase) * 5;
  }

  display() {
    noFill();

    stroke(180, 220, 255, 120);
    strokeWeight(1.4);
    circle(this.x, this.y, this.r * 2);

    stroke(80, 140, 255, 45);
    circle(this.x, this.y, this.r * 3.4);

    noStroke();
    fill(180, 230, 255, 180);
    circle(this.x, this.y, 3);
  }
}

function mousePressed() {
  for (let i = 0; i < 12; i++) {
    nodes.push(new NeuralCircle((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) + random(-40, 40), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) + random(-40, 40)));
  }
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
}

